# List and search R/Python files in code/ for ecological figure generation patterns
files <- list.files("code", full.names = TRUE)
for (f in files) {
  lines <- readLines(f, warn = FALSE)
  if (any(grepl("environmental_tolerance", lines))) {
    message(paste("Found 'environmental_tolerance' in:", f))
  }
  if (any(grepl("response_curves", lines))) {
    message(paste("Found 'response_curves' in:", f))
  }
}

# Read and grep the specific lines for environmental_tolerance in notebook_nod_general.R
lines <- readLines("code/notebook_nod_general.R")
match_idx <- which(grepl("environmental_tolerance", lines))
if (length(match_idx) > 0) {
  # print the context around each match (15 lines before and after)
  for (idx in match_idx) {
    start <- max(1, idx - 10)
    end <- min(length(lines), idx + 25)
    cat(sprintf("--- Context around line %d ---\n", idx))
    cat(paste(lines[start:end], collapse="\n"), "\n\n")
  }
} else {
  cat("No match found for 'environmental_tolerance' in code/notebook_nod_general.R\n")
}

# Scan for environmental_tolerance in the home directory files
files <- list.files("/home/user", pattern = "\\.[rR]$", full.names = TRUE)
for (f in files) {
  lines <- readLines(f, warn = FALSE)
  if (any(grepl("environmental_tolerance", lines))) {
    message(paste("Found 'environmental_tolerance' in:", f))
    match_idx <- which(grepl("environmental_tolerance", lines))
    for (idx in match_idx) {
      start <- max(1, idx - 10)
      end <- min(length(lines), idx + 25)
      cat(sprintf("--- Context around line %d in %s ---\n", idx, basename(f)))
      cat(paste(lines[start:end], collapse="\n"), "\n\n")
    }
  }
}

